import { describe, expect, it } from 'vitest';
import { setWith } from './setWith.ts';
import { symbol } from '../_internal/symbol.ts';
import { constant, each, map, toString, unset, update } from '../compat.ts';
import { isObject } from '../predicate/isObject.ts';

describe('setWith', () => {
  it('should work with a `customizer` callback', () => {
    const actual = setWith({ 0: {} }, '[0][1][2]', 3, value => (isObject(value) ? undefined : {}));

    expect(actual).toEqual({ 0: { 1: { 2: 3 } } });
  });

  it('should work with a `customizer` that returns `undefined`', () => {
    const actual = setWith({}, 'a[0].b.c', 4, () => undefined);
    expect(actual).toEqual({ a: [{ b: { c: 4 } }] });
  });

  const oldValue = 1;
  const value = 2;
  const updater = constant(value);

  it('should set property values', () => {
    each(['a', ['a']], path => {
      const object = { a: oldValue };
      const actual = update(object, path, updater);

      expect(actual).toBe(object);
      expect(object.a).toBe(value);
    });
  });

  it('should preserve the sign of `0`', () => {
    const props = [-0, Object(-0), 0, Object(0)];
    const expected = map(props, constant(value));

    const actual = map(props, key => {
      const object = { '-0': 'a', 0: 'b' };
      update(object, key, updater);
      return object[toString(key) as keyof typeof object];
    });

    expect(actual).toEqual(expected);
  });

  it('should unset symbol keyed property values', () => {
    const object: Record<symbol, unknown> = {};
    object[symbol] = 1;

    expect(unset(object, symbol)).toBe(true);
    expect(symbol in object).toBe(false);
  });

  it('should set deep property values', () => {
    each(['a.b', ['a', 'b']], path => {
      const object = { a: { b: oldValue } };
      const actual = update(object, path, updater);

      expect(actual).toBe(object);
      expect(object.a.b).toBe(value);
    });
  });

  it('should set a key over a path', () => {
    each(['a.b', ['a.b']], path => {
      const object = { 'a.b': oldValue };
      const actual = update(object, path, updater);

      expect(actual).toBe(object);
      expect(object).toEqual({ 'a.b': value });
    });
  });

  it('should not coerce array paths to strings', () => {
    const object = { 'a,b,c': 1, a: { b: { c: 1 } } };

    update(object, ['a', 'b', 'c'], updater);
    expect(object.a.b.c).toBe(value);
  });

  it('should not ignore empty brackets', () => {
    const object = {};

    update(object, 'a[]', updater);
    expect(object).toEqual({ a: { '': value } });
  });

  it('should handle empty paths', () => {
    each(
      [
        ['', ''],
        [[], ['']],
      ],
      (pair, index) => {
        const object = {};

        update(object, pair[0], updater);
        expect(object).toEqual(index ? {} : { '': value });

        update(object, pair[1], updater);
        expect(object).toEqual({ '': value });
      }
    );
  });

  it('should handle complex paths', () => {
    const object: any = {
      a: { 1.23: { '["b"]': { c: { "['d']": { '\ne\n': { f: { g: oldValue } } } } } } },
    };

    const paths = [
      'a[-1.23]["[\\"b\\"]"].c[\'[\\\'d\\\']\'][\ne\n][f].g',
      ['a', '-1.23', '["b"]', 'c', "['d']", '\ne\n', 'f', 'g'],
    ];

    each(paths, path => {
      update(object, path, updater);
      expect(object.a[-1.23]['["b"]'].c["['d']"]['\ne\n'].f.g).toBe(value);
      object.a[-1.23]['["b"]'].c["['d']"]['\ne\n'].f.g = oldValue;
    });
  });

  it('should create parts of `path` that are missing', () => {
    const object: any = {};

    each(['a[1].b.c', ['a', '1', 'b', 'c']], path => {
      const actual = update(object, path, updater);

      expect(actual).toBe(object);
      expect(actual).toEqual({ a: [undefined, { b: { c: value } }] });
      expect('0' in object.a).toBe(false);

      delete object.a;
    });
  });

  it('should not error when `object` is nullish', () => {
    const values = [null, undefined];
    const expected = [
      [null, null],
      [undefined, undefined],
    ];

    const actual = map(values, value => {
      try {
        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
        // @ts-expect-error
        return [update(value, 'a.b', updater), update(value, ['a', 'b'], updater)];
      } catch (e: unknown) {
        return e instanceof Error ? e.message : 'unknown error';
      }
    });

    expect(actual).toEqual(expected);
  });

  it('should overwrite primitives in the path', () => {
    each(['a.b', ['a', 'b']], path => {
      const object = { a: '' };

      update(object, path, updater);
      expect(object).toEqual({ a: { b: 2 } });
    });
  });

  it('should not create an array for missing non-index property names that start with numbers', () => {
    const object = {};

    update(object, ['1a', '2b', '3c'], updater);
    expect(object).toEqual({ '1a': { '2b': { '3c': value } } });
  });

  it('should not assign values that are the same as their destinations', () => {
    each(['a', ['a'], { a: 1 }, NaN], value => {
      const object = {};
      let pass = true;
      const updater = constant(value);

      Object.defineProperty(object, 'a', {
        configurable: true,
        enumerable: true,
        get: constant(value),
        set: function () {
          pass = false;
        },
      });

      update(object, 'a', updater);
      expect(pass).toBe(true);
    });
  });

  it('should invoke `updater` with the value on `path` of `object`', () => {
    const object = { a: [{ b: { c: oldValue } }] };
    const expected = oldValue + 1;

    each(['a[0].b.c', ['a', '0', 'b', 'c']], path => {
      update(object, path, (n: any) => {
        expect(n).toBe(oldValue);
        return ++n;
      });

      expect(object.a[0].b.c).toBe(expected);
      object.a[0].b.c = oldValue;
    });
  });

  it('should handle Object as customizer', () => {
    const actual = setWith({}, '[0][1]', 'a', Object);
    expect(actual).toEqual({ 0: { 1: 'a' } });
  });

  it('should return null when object is null', () => {
    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    // @ts-expect-error
    expect(setWith(null, 'a.b.c', 1)).toBeNull();
  });

  it('should return undefined when object is undefined', () => {
    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    // @ts-expect-error
    expect(setWith(undefined, 'a.b.c', 1)).toBeUndefined();
  });

  it('should work without a customizer', () => {
    const actual = setWith({}, 'a.b.c', 2);
    expect(actual).toEqual({ a: { b: { c: 2 } } });
  });

  it('should handle array paths', () => {
    const actual = setWith({}, ['a', 'b', 'c'], 3);
    expect(actual).toEqual({ a: { b: { c: 3 } } });
  });

  it('should handle number paths', () => {
    const obj: unknown[] = [];
    setWith(obj, 0, 'value');
    expect(obj).toEqual(['value']);
  });
});

src/compat/array/findLastIndex.spec.ts.source:
import { describe, expect, it } from 'vitest';
import { findLastIndex } from './findLastIndex';
import { args } from '../_internal/args';
import { falsey } from '../_internal/falsey';
import { slice } from '../_internal/slice';
import { stubZero } from '../_internal/stubZero';

describe('findLastIndex', () => {
  const objects = [
    { a: 0, b: 0, 0: 0, [Symbol.for('a')]: 0 },
    { a: 1, b: 1, 0: 1, [Symbol.for('a')]: 1 },
    { a: 2, b: 2, 0: 2, [Symbol.for('a')]: 2 },
  ];

  it(`should return the found value`, () => {
    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    // @ts-expect-error
    expect(findLastIndex(objects, object => object.a)).toEqual(2);
  });

  it(`should return -1 if value is not found`, () => {
    expect(findLastIndex(objects, object => object.a === 3)).toEqual(-1);
  });

  it(`findLastIndex should work with \`matches\` shorthands`, () => {
    expect(findLastIndex(objects, { b: 2 })).toBe(2);
  });

  it(`findLastIndex should work with \`matchesProperty\` shorthands`, () => {
    expect(findLastIndex(objects, ['b', 2])).toBe(2);
    expect(findLastIndex(objects, [0, 2])).toBe(2);
    expect(findLastIndex(objects, [Symbol.for('a'), 2])).toBe(2);
  });

  it(`findLastIndex should work with \`property\` shorthands`, () => {
    expect(findLastIndex(objects, 'b')).toBe(2);
    expect(findLastIndex(objects, 0)).toBe(2);
    expect(findLastIndex(objects, Symbol.for('a'))).toBe(2);
  });

  it(`findLastIndex should provide correct \`predicate\` arguments for arrays`, () => {
    let args: any;
    const array = ['a'];

    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    // @ts-expect-error
    findLastIndex(array, function () {
      // eslint-disable-next-line
      args || (args = slice.call(arguments));
    });

    expect(args).toEqual(['a', 0, array]);
  });

  const array = [1, 2, 3, 1, 2, 3];

  it(`\`findLastIndex\` should return the index of the last matched value`, () => {
    expect(findLastIndex(array, x => x === 3)).toBe(5);
  });

  it(`\`findLastIndex\` should work with a positive \`fromIndex\``, () => {
    expect(findLastIndex(array, x => x === 1, 2)).toBe(0);
  });

  it(`\`findLastIndex\` should work with a \`fromIndex\` >= \`length\``, () => {
    const values = [6, 8, 2 ** 32, Infinity];
    const expected = values.map(() => [-1, 3, -1]);

    const actual = values.map(fromIndex => [
      findLastIndex(array, x => x === undefined, fromIndex),
      findLastIndex(array, x => x === 1, fromIndex),
      // eslint-disable-next-line
      // @ts-ignore
      findLastIndex(array, x => x === '', fromIndex),
    ]);

    expect(actual).toEqual(expected);
  });

  it(`\`findLastIndex\` should work with a negative \`fromIndex\``, () => {
    expect(findLastIndex(array, x => x === 2, -3)).toBe(1);
  });

  it(`\`findLastIndex\` should work with a negative \`fromIndex\` <= \`-length\``, () => {
    const values = [-6, -8, -Infinity];
    const expected = values.map(stubZero);

    const actual = values.map(fromIndex => findLastIndex(array, x => x === 1, fromIndex));

    expect(actual).toEqual(expected);
  });

  it(`\`findLastIndex\` should treat falsey \`fromIndex\` values correctly`, () => {
    const expected = falsey.map(value => (value === undefined ? 5 : -1));

    const actual = falsey.map(fromIndex =>
      // eslint-disable-next-line
      // @ts-ignore
      findLastIndex(array, x => x === 3, fromIndex)
    );

    expect(actual).toEqual(expected);
  });

  it(`\`findLastIndex\` should coerce \`fromIndex\` to an integer`, () => {
    expect(findLastIndex(array, x => x === 2, 4.2)).toBe(4);
    // `fromIndex` is truncated toward zero, so the search starts at index 5, 2, and 6.
    expect(findLastIndex(array, x => x === 3, -1.5)).toBe(5);
    expect(findLastIndex(array, x => x === 3, -4.5)).toBe(2);
    expect(findLastIndex(array, x => x === 3, -0.5)).toBe(5);
  });

  it(`\`findLastIndex\` should coerce a non-numeric \`fromIndex\` like lodash`, () => {
    // eslint-disable-next-line
    // @ts-ignore
    expect(findLastIndex(array, x => x === 1, '-2')).toBe(3);
    // eslint-disable-next-line
    // @ts-ignore
    expect(findLastIndex(array, x => x === 1, 'abc')).toBe(0);
  });

  it(`\`findLastIndex\` with \`NaN\` \`fromIndex\` should start from 0`, () => {
    // Lodash coerces `NaN` via `toInteger`, so `fromIndex` becomes `0` and the
    // search still covers the first element. The existing falsey test uses a
    // predicate that never matches index 0, so it does not catch this.
    expect(findLastIndex(array, x => x === 1, NaN)).toBe(0);
  });

  it('should return `-1` when provided `null` or `undefined`', () => {
    expect(findLastIndex(null, 'a')).toBe(-1);
    expect(findLastIndex(undefined, 'a')).toBe(-1);
  });

  it('should support array-like objects', () => {
    expect(findLastIndex({ 0: 'a', 1: 'b', length: 2 }, i => i === 'b')).toBe(1);
    expect(findLastIndex('123', i => i === '2')).toBe(1);
    expect(findLastIndex(args, i => i === 2)).toBe(1);
  });

  it('should use identity function when no predicate is provided', () => {
    expect(findLastIndex([null, undefined, 0, 'hello', 'world'])).toBe(4);
    expect(findLastIndex([false, '', 0, 1, 2, null])).toBe(4);
  });

  it('should work with no predicate (uses identity)', () => {
    expect(findLastIndex([0, false, null, undefined, '', 1, 2, 3])).toBe(7);
    expect(findLastIndex([0, false, null, undefined, ''])).toBe(-1);
  });
});

src/compat/util/iteratee.spec.ts.source:
import { describe, expect, it } from 'vitest';
import { iteratee } from './iteratee';
import { stubFalse } from './stubFalse';
import { slice } from '../_internal/slice';
import { partial, partialRight } from '../index';
import * as esToolkit from '../index';

describe('iteratee', () => {
  it('should provide arguments to `func`', () => {
    const fn = function () {
      // eslint-disable-next-line prefer-rest-params
      return slice.call(arguments);
    };
    const iterateeFn = iteratee(fn);
    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    // @ts-expect-error
    const actual = iterateeFn('a', 'b', 'c', 'd', 'e', 'f');

    expect(actual).toEqual(['a', 'b', 'c', 'd', 'e', 'f']);
  });

  it('should return `_.identity` when `func` is nullish', () => {
    const object = {};
    // eslint-disable-next-line no-sparse-arrays
    const values = [, null, undefined];
    const expected = values.map(esToolkit.constant(object));

    const actual = values.map((value, index) => {
      // eslint-disable-next-line @typescript-eslint/ban-ts-comment
      // @ts-expect-error
      const identity = index ? iteratee(value) : iteratee();
      return identity(object);
    });

    expect(actual).toEqual(expected);
  });

  it('should return an iteratee created by `_.matches` when `func` is an object', () => {
    const matches = iteratee({ a: 1, b: 2 });
    expect(matches({ a: 1, b: 2, c: 3 })).toBe(true);
    expect(matches({ b: 2 })).toBe(false);
  });

  it('should not change `_.matches` behavior if `source` is modified', () => {
    const sources: any[] = [{ a: { b: 2, c: 3 } }, { a: 1, b: 2 }, { a: 1 }];

    sources.forEach((source, index) => {
      const object = esToolkit.cloneDeep(source);
      const matches = iteratee(source);

      expect(matches(object)).toBe(true);

      if (index) {
        source.a = 2;
        source.b = 1;
        source.c = 3;
      } else {
        source.a.b = 1;
        source.a.c = 2;
        source.a.d = 3;
      }
      expect(matches(object)).toBe(true);
      expect(matches(source)).toBe(false);
    });
  });

  it('should return an iteratee created by `_.matchesProperty` when `func` is an array', () => {
    const array = ['a', undefined];
    let matches = iteratee([0, 'a']);

    expect(matches(array)).toBe(true);

    matches = iteratee(['0', 'a']);
    expect(matches(array)).toBe(true);

    matches = iteratee([1, undefined]);
    expect(matches(array)).toBe(true);
  });

  it('should support deep paths for `_.matchesProperty` shorthands', () => {
    const object = { a: { b: { c: 1, d: 2 } } };
    const matches = iteratee(['a.b', { c: 1 }]);

    expect(matches(object)).toBe(true);
  });

  it('should not change `_.matchesProperty` behavior if `source` is modified', () => {
    const sources: any[] = [{ a: { b: 2, c: 3 } }, { a: 1, b: 2 }, { a: 1 }];

    sources.forEach((source, index) => {
      const object = { a: esToolkit.cloneDeep(source) };
      const matches = iteratee(['a', source]);

      expect(matches(object)).toBe(true);

      if (index) {
        source.a = 2;
        source.b = 1;
        source.c = 3;
      } else {
        source.a.b = 1;
        source.a.c = 2;
        source.a.d = 3;
      }
      expect(matches(object)).toBe(true);
      expect(matches({ a: source })).toBe(false);
    });
  });

  it('should return an iteratee created by `_.property` when `func` is a number or string', () => {
    const array = ['a'];
    let prop = iteratee(0);

    expect(prop(array)).toBe('a');

    prop = iteratee('0');
    expect(prop(array)).toBe('a');
  });

  it('should return an iteratee created by `_.property` when `func` is a boolean', () => {
    const object = { true: 'yes', false: 'no' };

    // @ts-expect-error - `boolean` isn't part of `iteratee`'s public type, matching `@types/lodash`
    let prop = iteratee(true);
    expect(prop(object)).toBe('yes');

    // @ts-expect-error - `boolean` isn't part of `iteratee`'s public type, matching `@types/lodash`
    prop = iteratee(false);
    expect(prop(object)).toBe('no');
  });

  it('should support deep paths for `_.property` shorthands', () => {
    const object = { a: { b: 2 } };
    const prop = iteratee('a.b');

    expect(prop(object)).toBe(2);
  });

  it('should work with functions created by `_.partial` and `_.partialRight`', () => {
    const fn = function (this: any) {
      const result = [this.a];
      // eslint-disable-next-line prefer-rest-params
      Array.prototype.push.apply(result, arguments as any);
      return result;
    };

    const expected = [1, 2, 3];
    const object = { a: 1, iteratee: iteratee(partial(fn, 2)) };

    // eslint-disable-next-line
    // @ts-ignore
    expect(object.iteratee(3)).toEqual(expected);

    object.iteratee = iteratee(partialRight(fn, 3));
    // eslint-disable-next-line
    // @ts-ignore
    expect(object.iteratee(2)).toEqual(expected);
  });

  // it('should use internal `iteratee` if external is unavailable', () => {
  //   const iteratee = _.iteratee;
  //   delete _.iteratee;

  //   expect(map([{ a: 1 }], 'a')).toEqual([1]);

  //   _.iteratee = iteratee;
  // });

  it('should work as an iteratee for methods like `_.map`', () => {
    const fn = function (this: any) {
      return this instanceof Number;
    };
    const array = [fn, fn, fn];
    const iteratees = array.map(iteratee);
    const expected = array.map(stubFalse);

    const actual = iteratees.map(iteratee => iteratee());

    expect(actual).toEqual(expected);
  });
});

